CREATE OR REPLACE FUNCTION public.calculate_collaborator_revenue_split()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  share_percent DECIMAL;
BEGIN
  SELECT revenue_share_percent INTO share_percent
  FROM collaborators
  WHERE id = NEW.collaborator_id;
  
  NEW.collaborator_share := NEW.order_total * (share_percent / 100);
  NEW.loption_share := NEW.order_total - NEW.collaborator_share;
  
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.calculate_driver_weekly_earnings()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  driver_record RECORD;
  v_week_start DATE;
  v_week_end DATE;
BEGIN
  -- Get current week (Monday to Sunday)
  v_week_start := date_trunc('week', CURRENT_DATE)::DATE;
  v_week_end := v_week_start + interval '6 days';
  
  FOR driver_record IN 
    SELECT 
      d.id as driver_id,
      COUNT(o.id) as total_deliveries,
      SUM(o.delivery_fee) as total_delivery_fees,
      SUM(o.delivery_fee) * 0.15 as commission_amount
    FROM drivers d
    JOIN orders o ON o.driver_id = d.id
    WHERE o.status = 'delivered'
      AND o.delivered_at >= v_week_start
      AND o.delivered_at <= v_week_end
      AND (o.driver_commission_paid IS NULL OR o.driver_commission_paid = false)
    GROUP BY d.id
  LOOP
    -- Insert or update weekly earnings
    INSERT INTO driver_weekly_earnings (
      driver_id, week_start, week_end,
      total_deliveries, total_delivery_fees, commission_rate, commission_amount,
      payout_status
    ) VALUES (
      driver_record.driver_id, v_week_start, v_week_end,
      driver_record.total_deliveries, driver_record.total_delivery_fees, 15, driver_record.commission_amount,
      'pending'
    )
    ON CONFLICT (driver_id, week_start) DO UPDATE SET
      total_deliveries = EXCLUDED.total_deliveries,
      total_delivery_fees = EXCLUDED.total_delivery_fees,
      commission_amount = EXCLUDED.commission_amount,
      updated_at = NOW();
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_order_transaction(p_order_number text, p_kiosk_id uuid, p_items jsonb, p_total numeric, p_language text, p_tracking_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_id UUID;
  v_item JSONB;
  v_product_id UUID;
  v_quantity INTEGER;
  v_product_name TEXT;
  v_unit_price DECIMAL;
BEGIN
  INSERT INTO orders (
    order_number, kiosk_id, total, language, status,
    timestamp, items, tracking_token, tracking_expires_at, created_at
  ) VALUES (
    p_order_number, p_kiosk_id, p_total, p_language, 'new',
    NOW(), p_items, p_tracking_token, NOW() + INTERVAL '24 hours', NOW()
  ) RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_quantity := (v_item->>'quantity')::INTEGER;
    
    SELECT name_en, price INTO v_product_name, v_unit_price
    FROM products WHERE id = v_product_id FOR UPDATE;
    
    IF NOT FOUND THEN RAISE EXCEPTION 'Product % not found', v_product_id; END IF;
    
    UPDATE products SET stock = stock - v_quantity, updated_at = NOW()
    WHERE id = v_product_id AND stock >= v_quantity;
    
    IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient stock for product %', v_product_id; END IF;
    
    INSERT INTO order_items (order_id, product_id, product_name, unit_price, quantity)
    VALUES (v_order_id, v_product_id, v_product_name, v_unit_price, v_quantity);
    
    INSERT INTO stock_movements (product_id, quantity_change, reason, order_id)
    VALUES (v_product_id, -v_quantity, 'order', v_order_id);
  END LOOP;

  UPDATE kiosks SET last_seen = NOW() WHERE id = p_kiosk_id;

  RETURN jsonb_build_object('success', true, 'order_id', v_order_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_collaborator_analytics()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  INSERT INTO collaborator_analytics (collaborator_id, date, total_orders, completed_orders, total_revenue, collaborator_revenue, loption_revenue)
  VALUES (
    NEW.collaborator_id,
    CURRENT_DATE,
    1,
    CASE WHEN NEW.preparation_status = 'ready' THEN 1 ELSE 0 END,
    NEW.order_total,
    NEW.collaborator_share,
    NEW.loption_share
  )
  ON CONFLICT (collaborator_id, date) DO UPDATE SET
    total_orders = collaborator_analytics.total_orders + 1,
    completed_orders = collaborator_analytics.completed_orders + 
      CASE WHEN NEW.preparation_status = 'ready' THEN 1 ELSE 0 END,
    total_revenue = collaborator_analytics.total_revenue + NEW.order_total,
    collaborator_revenue = collaborator_analytics.collaborator_revenue + NEW.collaborator_share,
    loption_revenue = collaborator_analytics.loption_revenue + NEW.loption_share;
  
  RETURN NEW;
END;
$function$;

CREATE TRIGGER trigger_calculate_revenue_split BEFORE INSERT ON public.collaborator_orders FOR EACH ROW EXECUTE FUNCTION calculate_collaborator_revenue_split();
CREATE TRIGGER trigger_update_analytics AFTER INSERT OR UPDATE OF preparation_status ON public.collaborator_orders FOR EACH ROW EXECUTE FUNCTION update_collaborator_analytics();

