-- storage.objects policies: only when the platform storage schema exists.
do $storage$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'baseline: storage.objects absent, storage policies skipped';
    return;
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'Authenticated users can upload') then
    execute $p$create policy "Authenticated users can upload" on storage."objects" as permissive for insert to public
  with check (((bucket_id = 'meal-images'::text) AND (auth.role() = 'authenticated'::text)));$p$;
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'Public Access') then
    execute $p$create policy "Public Access" on storage."objects" as permissive for select to public
  using ((bucket_id = 'meal-images'::text));$p$;
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'Users can delete own uploads') then
    execute $p$create policy "Users can delete own uploads" on storage."objects" as permissive for delete to public
  using (((bucket_id = 'meal-images'::text) AND (auth.uid() = owner)));$p$;
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'Users can update own uploads') then
    execute $p$create policy "Users can update own uploads" on storage."objects" as permissive for update to public
  using (((bucket_id = 'meal-images'::text) AND (auth.uid() = owner)));$p$;
  end if;
end
$storage$;

